<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreTransportPersonRequest;use App\Models\{Empleado,TransportPerson};use App\Services\TransportAuditService;
class TransportPersonController extends Controller {public function index(){ $company=auth()->user()->company_id;return view('transport.people.index',['people'=>TransportPerson::forCompany($company)->with('employee')->latest()->paginate(20),'employees'=>Empleado::where('company_id',$company)->active()->orderBy('nombre_completo')->get()]);}public function store(StoreTransportPersonRequest $r,TransportAuditService $audit){$data=$r->validated();if($data['person_type']==='employee'){$data['name']=$data['document_type']=$data['document_number']=$data['phone']=$data['provider']=null;}else{$data['employee_id']=null;}$p=TransportPerson::create($data+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id]);$audit->record($p->company_id,'transport_person_created','person',$p->id,$r->user()->id);return back()->with('success','Personal de transporte registrado.');}public function update(StoreTransportPersonRequest $r,TransportPerson $person,TransportAuditService $audit){$this->own($person);$data=$r->validated();if($data['person_type']==='employee'){$data['name']=$data['document_type']=$data['document_number']=$data['phone']=$data['provider']=null;}else{$data['employee_id']=null;}$person->update($data+['updated_by'=>$r->user()->id]);$audit->record($person->company_id,'transport_person_updated','person',$person->id,$r->user()->id);return back()->with('success','Personal actualizado.');}public function destroy(TransportPerson $person,TransportAuditService $audit){$this->own($person);$person->update(['status'=>'inactive','updated_by'=>auth()->id()]);$audit->record($person->company_id,'transport_person_deactivated','person',$person->id,auth()->id());return back()->with('success','Perfil desactivado sin borrar su historial.');}private function own($m):void{abort_unless((int)$m->company_id===(int)auth()->user()->company_id,404);}}
